type Product = { id:string; sku:string; name:string; genericName:string; brand:string; category:string; dosageForm:string; strength:string; unit:string; barcode:string; batchNumber:string; supplierId:string; purchasePrice:number; sellingPrice:number; quantity:number; minStock:number; maxStock:number; manufactureDate:string; expiryDate:string; prescriptionRequired:boolean; status:string; description:string };
type Customer = { id:string; name:string; phone:string; email:string; address:string; loyalty:number; createdAt:string };
type Supplier = { id:string; name:string; contact:string; phone:string; email:string; address:string; terms:string };
type Staff = { id:string; name:string; role:string; phone:string; email:string; status:string };
type Line = { productId:string; name:string; qty:number; cost:number; price:number };
type Sale = { id:string; invoice:string; customerId:string; customer:string; timestamp:string; payment:string; status:string; items:Line[]; total:number };
type Purchase = { id:string; invoice:string; supplierId:string; supplier:string; date:string; status:string; items:Line[]; total:number };
type Movement = { id:string; productId:string; product:string; delta:number; kind:string; reference:string; timestamp:string; note:string };
type Store = { products:Product[]; customers:Customer[]; suppliers:Supplier[]; staff:Staff[]; sales:Sale[]; purchases:Purchase[]; movements:Movement[]; settings:{pharmacyName:string; currency:string; tax:number; lowStock:number; expiryDays:number; address:string; phone:string} };

