const localDate=(date:Date)=>`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;
const today=()=>localDate(new Date());
const days=(n:number)=>{const date=new Date();date.setDate(date.getDate()+n);return localDate(date)};
const daysUntilExpiry=(value:string)=>{const [year,month,day]=value.split('-').map(Number);const now=new Date();return Math.round((Date.UTC(year,month-1,day)-Date.UTC(now.getFullYear(),now.getMonth(),now.getDate()))/86400000)};
